SELECT
  o.order_no,
  o.order_date,
  o.due_date,
  i.item_name,
  o.order_qty,
  o.status
FROM orders o
LEFT JOIN items i ON o.item_id = i.id


    o.order_no = #{criteria.orderNo}


    AND o.status = #{criteria.status}


    AND o.order_date >= #{criteria.fromDate}


    AND o.order_date <= #{criteria.toDate}


ORDER BY o.id DESC

  LIMIT #{criteria.limit} OFFSET #{criteria.offset}
